# Generated by Descant: acceptance tests.

# frozen_string_literal: true

RSpec.describe TimekeepingRules::EntryRules, ".agent_owner" do
  # The issue: the API "still commits any positive agent_id without checking
  # that the agent exists and belongs to the entry's company and user (design
  # rule S7)". company_agents maps each agent of the entry's company to its user.
  it "answers not_found for an agent outside the company's agents or owned by another user, and ok only for the entry user's own agent" do
    company_agents = { 31 => 7, 32 => 8 }

    expect(described_class.agent_owner(agent_id: 99, user_id: 7, company_agents:)).to eq(:not_found)
    expect(described_class.agent_owner(agent_id: 32, user_id: 7, company_agents:)).to eq(:not_found)
    expect(described_class.agent_owner(agent_id: 31, user_id: 7, company_agents: {})).to eq(:not_found)
    expect(described_class.agent_owner(agent_id: "31", user_id: 7, company_agents:)).to eq(:not_found)
    expect(described_class.agent_owner(agent_id: 31, user_id: 7, company_agents:)).to eq(:ok)
    expect(described_class.agent_owner(agent_id: nil, user_id: 7, company_agents:)).to eq(:ok)
  end
end
